			"framesize",
			"num_skins",
			"num_vertices",
			"num_st",
			"num_tris",
			"num_glcmds",
			"num_frames",
			"offset_skins",
			"offset_st",
			"offset_tris",
			"offset_frames",
			"offset_glcmds",
			"offset_end"
